<?php
declare(strict_types=1);
if(session_status()!==PHP_SESSION_ACTIVE){session_set_cookie_params(['httponly'=>true,'secure'=>!empty($_SERVER['HTTPS']),'samesite'=>'Lax']);session_start();}
$cfgFile=__DIR__.'/../config.php';$cfg=is_file($cfgFile)?require $cfgFile:[];
function db():PDO{static $p;if($p)return $p;global $cfg;if(empty($cfg['db_name']))throw new RuntimeException('Copy config.example.php to config.php and configure MySQL.');$p=new PDO('mysql:host='.$cfg['db_host'].';dbname='.$cfg['db_name'].';charset=utf8mb4',$cfg['db_user'],$cfg['db_pass'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);return $p;}
function e(mixed $v):string{return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
function current_user():?array{return $_SESSION['user']??null;}
function csrf_token():string{if(empty($_SESSION['csrf']))$_SESSION['csrf']=bin2hex(random_bytes(32));return $_SESSION['csrf'];}
function flash(string $v):void{$_SESSION['flash']=$v;}
function flash_message():?string{$v=$_SESSION['flash']??null;unset($_SESSION['flash']);return $v;}
function go(string $v='?page=dashboard'):never{header('Location: '.$v);exit;}
function require_login():void{if(!current_user())go('?page=login');}
function categories():array{return db()->query('SELECT id,name FROM categories ORDER BY sort_order,name')->fetchAll();}
function public_businesses(string $q='',string $cat=''):array{$sql="SELECT b.*,c.name category_name,COALESCE(AVG(r.rating),0) avg_rating,COUNT(DISTINCT r.id) review_count FROM businesses b JOIN categories c ON c.id=b.category_id LEFT JOIN reviews r ON r.business_id=b.id AND r.status='approved' WHERE b.status='approved'";$a=[];if($q!==''){$sql.=' AND (b.name LIKE ? OR b.description LIKE ? OR b.address LIKE ? OR b.phone LIKE ? OR c.name LIKE ?)';for($i=0;$i<5;$i++){$a[]='%'.$q.'%';}}if($cat!==''&&ctype_digit((string)$cat)){$sql.=' AND b.category_id=?';$a[]=(int)$cat;}$sql.=' GROUP BY b.id ORDER BY b.is_featured DESC,b.created_at DESC';$s=db()->prepare($sql);$s->execute($a);return $s->fetchAll();}
function business_by_id(int $id):?array{$s=db()->prepare("SELECT b.*,c.name category_name,COALESCE(AVG(CASE WHEN r.status='approved' THEN r.rating END),0) avg_rating,SUM(CASE WHEN r.status='approved' THEN 1 ELSE 0 END) review_count FROM businesses b JOIN categories c ON c.id=b.category_id LEFT JOIN reviews r ON r.business_id=b.id WHERE b.id=? GROUP BY b.id");$s->execute([$id]);return $s->fetch()?:null;}
function business_card(array $b):void{?><article class="business-card"><a class="card-photo" href="?page=business&id=<?= (int)$b['id'] ?>" style="background-image:url('<?= e($b['cover_image']?:'assets/cover.svg') ?>')"><span class="card-category"><?= e($b['category_name']) ?></span><span class="card-rating">★ <?= (float)$b['avg_rating']>0?number_format((float)$b['avg_rating'],1):'I ri' ?></span></a><div class="card-content"><a class="card-title" href="?page=business&id=<?= (int)$b['id'] ?>"><?= e($b['name']) ?></a><p><?= e(function_exists('mb_strimwidth')?mb_strimwidth($b['description']??'',0,95,'…'):substr($b['description']??'',0,95)) ?></p><div class="card-bottom"><span>⌖ <?= e($b['address']?:'Lipjan') ?></span><a href="?page=business&id=<?= (int)$b['id'] ?>">Shiko biznesin ↗</a></div></div></article><?php }
function hours_list(string $j):array{$v=json_decode($j,true);$v=is_array($v)?$v:[];$days=['Monday'=>'E hënë','Tuesday'=>'E martë','Wednesday'=>'E mërkurë','Thursday'=>'E enjte','Friday'=>'E premte','Saturday'=>'E shtunë','Sunday'=>'E diel'];$out=[];foreach($days as $en=>$sq)$out[$sq]=$v[$en]??$v[$sq]??'Nuk është publikuar';return $out;}
function status_label(string $v):string{return ['pending'=>'Në pritje','draft'=>'Skicë','approved'=>'Miratuar','rejected'=>'Refuzuar'][$v]??$v;}
function business_images(int $id):array{$s=db()->prepare('SELECT path FROM business_images WHERE business_id=?');$s->execute([$id]);return $s->fetchAll();}
function reviews_for(int $id):array{$s=db()->prepare("SELECT r.*,u.full_name FROM reviews r JOIN users u ON u.id=r.user_id WHERE r.business_id=? AND r.status='approved' ORDER BY r.created_at DESC");$s->execute([$id]);return $s->fetchAll();}
function record_view(int $id):void{if(!isset($_SESSION['viewed_'.$id])){db()->prepare('UPDATE businesses SET views=views+1 WHERE id=?')->execute([$id]);$_SESSION['viewed_'.$id]=true;}}
function image_upload(string $field):?string{if(empty($_FILES[$field]['name']))return null;$f=$_FILES[$field];if($f['error']!==UPLOAD_ERR_OK||$f['size']>5242880)throw new RuntimeException('Fotografitë duhet të jenë më të vogla se 5 MB.');$mime=(new finfo(FILEINFO_MIME_TYPE))->file($f['tmp_name']);$ext=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'][$mime]??null;if(!$ext)throw new RuntimeException('Ngarko fotografi JPG, PNG ose WebP.');$dir=__DIR__.'/../uploads';if(!is_dir($dir))mkdir($dir,0755,true);$name=bin2hex(random_bytes(16)).'.'.$ext;if(!move_uploaded_file($f['tmp_name'],$dir.'/'.$name))throw new RuntimeException('Ngarkimi i fotografisë dështoi.');return 'uploads/'.$name;}
function handle_post():void{try{if(!hash_equals(csrf_token(),(string)($_POST['csrf']??'')))throw new RuntimeException('Seanca skadoi. Provo përsëri.');$a=$_POST['action']??'';$p=db();
if($a==='register'){$role=($_POST['role']??'')==='owner'?'owner':'customer';$name=trim($_POST['full_name']??'');$email=strtolower(trim($_POST['email']??''));$phone=trim($_POST['phone']??'');$pw=$_POST['password']??'';if(!$name||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($pw)<8||$pw!==($_POST['confirm_password']??''))throw new RuntimeException('Kontrollo të dhënat dhe fjalëkalimet (të paktën 8 karaktere).');$p->prepare('INSERT INTO users(full_name,email,phone,password_hash,role) VALUES(?,?,?,?,?)')->execute([$name,$email,$phone,password_hash($pw,PASSWORD_DEFAULT),$role]);$id=(int)$p->lastInsertId();if($role==='owner'&&!empty($_POST['business_name']))$p->prepare("INSERT INTO businesses(owner_id,name,phone,status) VALUES(?,?,?,'draft')")->execute([$id,trim($_POST['business_name']),$phone]);$s=$p->prepare('SELECT id,full_name,email,role FROM users WHERE id=?');$s->execute([$id]);$_SESSION['user']=$s->fetch();flash('Llogaria u krijua. Mirë se erdhe!');go();}
if($a==='login'){$key=trim($_POST['email']??'');$role=$_POST['role']??'customer';if($role==='admin'){$s=$p->prepare("SELECT * FROM users WHERE email=? AND role='admin'");$s->execute([strtolower($key)]);}else{$s=$p->prepare("SELECT * FROM users WHERE (email=? OR phone=?) AND role IN ('owner','customer')");$s->execute([strtolower($key),$key]);}$u=$s->fetch();if(!$u||!password_verify($_POST['password']??'',$u['password_hash']))throw new RuntimeException('Të dhënat e hyrjes nuk janë të sakta.');unset($u['password_hash']);session_regenerate_id(true);$_SESSION['user']=$u;flash('Hyrja u krye me sukses.');go();}
require_login();$u=current_user();
if($a==='business_save'&&$u['role']==='owner'){$id=(int)($_POST['id']??0);$lat=filter_var($_POST['latitude']??'',FILTER_VALIDATE_FLOAT);$lng=filter_var($_POST['longitude']??'',FILTER_VALIDATE_FLOAT);$name=trim($_POST['name']??'');$address=trim($_POST['address']??'');if(!$name||!$address||$lat===false||$lng===false||$lat<42.40||$lat>42.65||$lng<20.90||$lng>21.25)throw new RuntimeException('Shkruaj adresën dhe cakto vendndodhjen e saktë në Lipjan në hartë.');$hours=[];foreach(['E hënë','E martë','E mërkurë','E enjte','E premte','E shtunë','E diel'] as $d)$hours[$d]=trim($_POST['hours'][$d]??'Mbyll');$logo=image_upload('logo');$cover=image_upload('cover');$vals=[$name,(int)($_POST['category_id']??0),$_POST['description']??'',trim($_POST['phone']??''),$address,$lat,$lng,json_encode($hours),$logo,$cover];if($id){$s=$p->prepare('SELECT id FROM businesses WHERE id=? AND owner_id=?');$s->execute([$id,$u['id']]);if(!$s->fetch())throw new RuntimeException('Biznesi nuk u gjet.');$p->prepare("UPDATE businesses SET name=?,category_id=?,description=?,phone=?,address=?,latitude=?,longitude=?,hours_json=?,logo=COALESCE(?,logo),cover_image=COALESCE(?,cover_image),status='pending' WHERE id=? AND owner_id=?")->execute([...$vals,$id,$u['id']]);}else{$p->prepare("INSERT INTO businesses(owner_id,name,category_id,description,phone,address,latitude,longitude,hours_json,logo,cover_image,status) VALUES(?,?,?,?,?,?,?,?,?,?,?,'pending')")->execute([...$vals,$u['id']]);$id=(int)$p->lastInsertId();}$g=image_upload('gallery');if($g)$p->prepare('INSERT INTO business_images(business_id,path) VALUES(?,?)')->execute([$id,$g]);flash('Biznesi u ruajt dhe u dërgua për shqyrtim.');go();}
if($a==='review'&&$u['role']==='customer'){$id=(int)$_POST['business_id'];$r=(int)$_POST['rating'];$body=trim($_POST['body']??'');if($r<1||$r>5||strlen($body)<3)throw new RuntimeException('Zgjidh vlerësimin dhe shkruaj një koment të shkurtër.');$p->prepare("INSERT INTO reviews(business_id,user_id,rating,body,status) SELECT ?,?,?,?,'pending' FROM businesses WHERE id=? AND status='approved'")->execute([$id,$u['id'],$r,$body,$id]);flash('Vlerësimi u dërgua për moderim.');go('?page=business&id='.$id);}
if($a==='favorite'&&$u['role']==='customer'){$p->prepare('INSERT IGNORE INTO favorites(user_id,business_id) VALUES(?,?)')->execute([$u['id'],(int)$_POST['business_id']]);flash('U ruajt te të preferuarat.');go();}
if($u['role']==='admin')admin_action($a);throw new RuntimeException('Nuk ke leje për këtë veprim.');
}catch(Throwable $x){flash($x instanceof PDOException?(str_contains($x->getMessage(),'Duplicate')?'Kjo llogari ose ky vlerësim ekziston tashmë.':'Gabim në databazë. Kontrollo të dhënat.'):$x->getMessage());header('Location: '.($_SERVER['HTTP_REFERER']??'?'));exit;}}
function admin_action(string $a):void{$p=db();if($a==='business_status'){$id=(int)$_POST['id'];$status=($_POST['status']??'')==='approved'?'approved':'rejected';$p->prepare('UPDATE businesses SET status=? WHERE id=?')->execute([$status,$id]);$p->prepare('INSERT INTO admin_activity(admin_id,action,entity_type,entity_id) VALUES(?,?,?,?)')->execute([current_user()['id'],$status,'business',$id]);flash('Biznesi u përditësua.');go();}if($a==='review_status'){$p->prepare('UPDATE reviews SET status=? WHERE id=?')->execute([($_POST['status']??'')==='approved'?'approved':'rejected',(int)$_POST['id']]);flash('Vlerësimi u përditësua.');go();}if($a==='delete_business'){$p->prepare('DELETE FROM businesses WHERE id=?')->execute([(int)$_POST['id']]);flash('Biznesi u fshi.');go();}}
function track_call(int $id):void{if($id>0)db()->prepare('UPDATE businesses SET call_clicks=call_clicks+1 WHERE id=? AND status=\'approved\'')->execute([$id]);}
function owner_businesses():array{$s=db()->prepare('SELECT b.*,c.name category_name FROM businesses b LEFT JOIN categories c ON b.category_id=c.id WHERE b.owner_id=? ORDER BY b.created_at DESC');$s->execute([current_user()['id']]);return $s->fetchAll();}
function owner_dashboard():void{$bs=owner_businesses();?><section class="dashboard"><div class="dash-head"><div><div class="section-kicker">PANELI I PRONARIT</div><h1>Mirë se erdhe, <?= e(current_user()['full_name']) ?>.</h1><p>Menaxho biznesin dhe shiko si të zbulojnë klientët.</p></div><a class="button" href="?page=edit-business">+ Shto biznes</a></div><div class="stat-grid"><div class="stat-card"><span>BIZNESE</span><b><?= count($bs) ?></b></div><div class="stat-card"><span>SHIKIME TË PROFILIT</span><b><?= array_sum(array_column($bs,'views')) ?></b></div><div class="stat-card"><span>TELEFONATA</span><b><?= array_sum(array_column($bs,'call_clicks')) ?></b></div></div><?php if(($_GET['page']??'')==='edit-business')owner_form((int)($_GET['id']??0)); ?><div class="table-card"><h2>Bizneset e tua</h2><?php if(!$bs): ?><p>Nuk ke shtuar ende biznes. Shto biznesin tënd për të filluar.</p><?php else: ?><div class="table-scroll"><table><thead><tr><th>Biznes</th><th>Kategoria</th><th>Statusi</th><th>Shikime</th><th>Veprime</th></tr></thead><tbody><?php foreach($bs as $b): ?><tr><td><?= e($b['name']) ?></td><td><?= e($b['category_name']??'—') ?></td><td><span class="status status-<?= e($b['status']) ?>"><?= e(status_label($b['status'])) ?></span></td><td><?= (int)$b['views'] ?></td><td><a href="?page=edit-business&id=<?= (int)$b['id'] ?>">Ndrysho →</a></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></div></section><?php }
function owner_form(int $id):void{$b=null;if($id){$s=db()->prepare('SELECT * FROM businesses WHERE id=? AND owner_id=?');$s->execute([$id,current_user()['id']]);$b=$s->fetch();} ?><div class="form-panel"><h2><?= $b?'Ndrysho biznesin':'Shto biznes' ?></h2><p>Shkruaj vendndodhjen e saktë. Bizneset shqyrtohen para publikimit.</p><form method="post" enctype="multipart/form-data" class="business-form"><input type="hidden" name="action" value="business_save"><input type="hidden" name="csrf" value="<?= csrf_token() ?>"><?php if($id): ?><input type="hidden" name="id" value="<?= $id ?>"><?php endif; ?><label>Emri i biznesit<input name="name" required value="<?= e($b['name']??'') ?>"></label><label>Kategoria<select name="category_id" required><option value="">Zgjidh</option><?php foreach(categories() as $c): ?><option value="<?= (int)$c['id'] ?>" <?= (($b['category_id']??'')==$c['id'])?'selected':'' ?>><?= e($c['name']) ?></option><?php endforeach; ?></select></label><label>Telefoni<input name="phone" type="tel" required value="<?= e($b['phone']??'') ?>"></label><label>Adresa e rrugës<input name="address" required value="<?= e($b['address']??'') ?>" placeholder="Rruga dhe numri, Lipjan"></label><label class="wide">Përshkrimi<textarea name="description" rows="4"><?= e($b['description']??'') ?></textarea></label><div class="wide"><p>Kliko në hartë për të caktuar vendndodhjen e saktë të biznesit në Lipjan.</p><div id="picker-map" class="picker-map" data-lat="<?= e($b['latitude']??'42.5215') ?>" data-lng="<?= e($b['longitude']??'21.1650') ?>"></div></div><label>Gjerësia gjeografike<input name="latitude" id="latitude" required value="<?= e($b['latitude']??'') ?>"></label><label>Gjatësia gjeografike<input name="longitude" id="longitude" required value="<?= e($b['longitude']??'') ?>"></label><?php foreach(['E hënë','E martë','E mërkurë','E enjte','E premte','E shtunë','E diel'] as $d): ?><label><?= $d ?> orari<input name="hours[<?= $d ?>]" value="<?= e(hours_list($b['hours_json']??'{}')[$d]??'Mbyll') ?>"></label><?php endforeach; ?><label>Logoja<input type="file" name="logo" accept="image/jpeg,image/png,image/webp"></label><label>Fotografia e kopertinës<input type="file" name="cover" accept="image/jpeg,image/png,image/webp"></label><label class="wide">Foto e galerisë<input type="file" name="gallery" accept="image/jpeg,image/png,image/webp"></label><div class="wide"><button class="button">Ruaj dhe dërgo për shqyrtim →</button></div></form></div><?php }
function customer_dashboard():void{$s=db()->prepare('SELECT b.* FROM favorites f JOIN businesses b ON f.business_id=b.id WHERE f.user_id=? AND b.status=\'approved\'');$s->execute([current_user()['id']]);?><section class="dashboard"><div class="section-kicker">LLOGARIA JOTE</div><h1>Mirë se erdhe, <?= e(current_user()['full_name']) ?>.</h1><p>Bizneset e tua të ruajtura.</p><div class="business-grid"><?php foreach($s->fetchAll() as $b){$x=business_by_id((int)$b['id']);if($x)business_card($x);} ?></div></section><?php }
function admin_dashboard():void{$p=db()->query('SELECT status,COUNT(*) n FROM businesses GROUP BY status')->fetchAll(PDO::FETCH_KEY_PAIR);$total=(int)db()->query('SELECT COUNT(*) FROM businesses')->fetchColumn();$customers=(int)db()->query("SELECT COUNT(*) FROM users WHERE role='customer'")->fetchColumn();$owners=(int)db()->query("SELECT COUNT(*) FROM users WHERE role='owner'")->fetchColumn();$visits=(int)db()->query('SELECT COUNT(*) FROM site_visits')->fetchColumn();$rows=db()->query("SELECT b.*,u.full_name owner_name,c.name category_name FROM businesses b LEFT JOIN users u ON u.id=b.owner_id LEFT JOIN categories c ON c.id=b.category_id ORDER BY FIELD(b.status,'pending','draft','approved','rejected'),b.created_at DESC")->fetchAll();$reviews=db()->query('SELECT r.*,b.name business_name,u.full_name FROM reviews r JOIN businesses b ON b.id=r.business_id JOIN users u ON u.id=r.user_id ORDER BY r.created_at DESC LIMIT 30')->fetchAll();?><section class="dashboard"><div class="section-kicker">ADMINISTRIMI I PLATFORMËS</div><h1>Paneli i administratorit</h1><p>Shqyrto bizneset dhe menaxho direktorinë e Lipjanit.</p><div class="stat-grid"><?php foreach(['BIZNESE'=>$total,'KLIENTË'=>$customers,'PRONARË BIZNESI'=>$owners,'NË PRITJE TË MIRATIMIT'=>(int)($p['pending']??0),'TË MIRATUARA'=>(int)($p['approved']??0),'TË REFUZUARA'=>(int)($p['rejected']??0),'VIZITA TË REGJISTRUARA'=>$visits] as $k=>$v): ?><div class="stat-card"><span><?= $k ?></span><b><?= $v ?></b></div><?php endforeach; ?></div><div class="table-card"><h2>Bizneset</h2><div class="table-scroll"><table><thead><tr><th>Biznes</th><th>Pronari</th><th>Kategoria</th><th>Statusi</th><th>Adresa</th><th>Veprime</th></tr></thead><tbody><?php foreach($rows as $b): ?><tr><td><?= e($b['name']) ?></td><td><?= e($b['owner_name']??'—') ?></td><td><?= e($b['category_name']??'—') ?></td><td><?= e(status_label($b['status'])) ?></td><td><?= e($b['address']??'E papërcaktuar') ?></td><td><?php foreach(['approved'=>'Mirato','rejected'=>'Refuzo'] as $st=>$label): ?><form method="post" class="inline-form"><input type="hidden" name="csrf" value="<?= csrf_token() ?>"><input type="hidden" name="action" value="business_status"><input type="hidden" name="id" value="<?= (int)$b['id'] ?>"><button name="status" value="<?= $st ?>"><?= $label ?></button></form><?php endforeach; ?><form method="post" class="inline-form" onsubmit="return confirm('Ta fshij këtë biznes?')"><input type="hidden" name="csrf" value="<?= csrf_token() ?>"><input type="hidden" name="action" value="delete_business"><input type="hidden" name="id" value="<?= (int)$b['id'] ?>"><button>Fshi</button></form></td></tr><?php endforeach; ?></tbody></table></div></div><div class="table-card"><h2>Moderimi i vlerësimeve</h2><div class="table-scroll"><table><thead><tr><th>Biznes</th><th>Klient</th><th>Yje</th><th>Vlerësimi</th><th>Moderim</th></tr></thead><tbody><?php foreach($reviews as $r): ?><tr><td><?= e($r['business_name']) ?></td><td><?= e($r['full_name']) ?></td><td><?= (int)$r['rating'] ?></td><td><?= e($r['body']) ?></td><td><form method="post" class="inline-form"><input type="hidden" name="csrf" value="<?= csrf_token() ?>"><input type="hidden" name="action" value="review_status"><input type="hidden" name="id" value="<?= (int)$r['id'] ?>"><button name="status" value="approved">Mirato</button><button name="status" value="rejected">Hiq</button></form></td></tr><?php endforeach; ?></tbody></table></div></div></section><?php }
